func TestBuildMemoryTagIndex(t *testing.T) {
	type sample struct {
		Top bool
		DB  struct {
			Inner int16
		}
		hidden bool
	}

	tags := buildMemoryTagIndex(reflect.TypeOf(sample{}))
	if len(tags) < 2 {
		t.Fatalf("buildMemoryTagIndex() len=%d, want >=2", len(tags))
	}
	var hasInner bool
	var hasTop bool
	for _, tag := range tags {
		if tag.Name == "DB.Inner" {
			hasInner = true
		}
		if tag.Name == "Top" {
			hasTop = true
		}
	}
	if !hasInner || !hasTop {
		t.Fatalf("missing expected tags in %+v", tags)
	}
}

