func TestOPCUASelfSignedCertIncludesAdvertisedSANs(t *testing.T) {
	appURI := opcuaApplicationURI()

	t.Run("DNS host", func(t *testing.T) {
		certPath, _, cleanup, err := writeOPCUASelfSignedCert("plc.example.local", appURI)
		if err != nil {
			t.Fatalf("writeOPCUASelfSignedCert() error: %v", err)
		}
		defer cleanup()
		cert := readOPCUATestCertificate(t, certPath)
		if !opcuaTestHasDNS(cert.DNSNames, "localhost") || !opcuaTestHasDNS(cert.DNSNames, "plc.example.local") {
			t.Fatalf("DNSNames=%v, want localhost and advertised host", cert.DNSNames)
		}
		if !opcuaTestHasIP(cert.IPAddresses, "127.0.0.1") {
			t.Fatalf("IPAddresses=%v, want 127.0.0.1", cert.IPAddresses)
		}
		if !opcuaTestHasURI(cert, appURI) {
			t.Fatalf("URIs=%v, want %s", cert.URIs, appURI)
		}
	})

	t.Run("IP host", func(t *testing.T) {
		certPath, _, cleanup, err := writeOPCUASelfSignedCert("::1", appURI)
		if err != nil {
			t.Fatalf("writeOPCUASelfSignedCert() error: %v", err)
		}
		defer cleanup()
		cert := readOPCUATestCertificate(t, certPath)
		if !opcuaTestHasIP(cert.IPAddresses, "127.0.0.1") || !opcuaTestHasIP(cert.IPAddresses, "::1") {
			t.Fatalf("IPAddresses=%v, want loopback and advertised IPv6", cert.IPAddresses)
		}
		if !opcuaTestHasURI(cert, appURI) {
			t.Fatalf("URIs=%v, want %s", cert.URIs, appURI)
		}
	})
}

