func TestTUISearchRendering(t *testing.T) {
	m := model{
		tags:   []memoryTag{{Name: "DB_Main.Counter"}, {Name: "System.Flag"}},
		values: []string{"1", "true"},
		height: 20,
		width:  80,
	}
	m.applyFilter()
	m.query = "db"
	m.applyFilter()
	view := m.View()
	if !strings.Contains(strings.ToLower(view), "db_main.counter") {
		t.Fatalf("view missing filtered tag: %q", view)
	}
	if strings.Contains(strings.ToLower(view), "system.flag") {
		t.Fatalf("view still contains non-matching tag: %q", view)
	}
}

